#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_speed;
uniform float amzp_intensity;
uniform float amzp_exposure;
uniform float amzp_opacity;





    const float PI = 3.14159265358979323846264;

    float2x2 ROT(float a){
      float c = cos(a), s = sin(a);
      return float2x2(c, s, -s, c);
    }


    float3 aces_approx(float3 v) {
      v = max(v, 0.0);
      v *= 0.6;
      float a = 2.51;
      float b = 0.03;
      float c = 2.43;
      float d = 0.59;
      float e = 0.14;
      return clamp((v*(a*v+b))/(v*(c*v+d)+e), 0.0, 1.0);
    }


    const float planeDist = 0.5;
    const float furthest  = 16.0;
    const float fadeFrom  = 8.0;

    const float2  pathA = float2(0.31, 0.41);
    const float2  pathB = float2(1.0, 0.7071067811865476); 

    float3 offsetf(float z) {
      return float3(pathB * sin(pathA*z), z);
    }

    float3 doffsetf(float z) {
      return float3(pathA*pathB * cos(pathA*z), 1.0);
    }

    float3 ddoffsetf(float z) {
      return float3(-pathA*pathA*pathB * sin(pathA*z), 0.0);
    }

    float4 alphaBlend(float4 back, float4 front) {
      float w = front.w + back.w*(1.0-front.w);
      float3 xyz = (front.xyz*front.w + back.xyz*back.w*(1.0-front.w)) / max(w, 1e-6);
      return (w > 0.0) ? float4(xyz, w) : float4(0.0);
    }

    float pmin(float a, float b, float k) {
      float h = clamp(0.5 + 0.5*(b-a)/k, 0.0, 1.0);
      return mix(b, a, h) - k*h*(1.0-h);
    }

    float pabs(float a, float k) {
      return -pmin(a, -a, k);
    }


    float star5(float2 p, float r, float rf, float sm) {
      p = -p;
      const float2 k1 = float2(0.809016994375, -0.587785252292);
      const float2 k2 = float2(-k1.x, k1.y);
      p.x = abs(p.x);
      p -= 2.0*max(dot(k1,p), 0.0)*k1;
      p -= 2.0*max(dot(k2,p), 0.0)*k2;
      p.x = pabs(p.x, sm);
      p.y -= r;
      float2 ba = rf*float2(-k1.y, k1.x) - float2(0,1);
      float h = clamp(dot(p,ba)/dot(ba,ba), 0.0, r);
      return length(p - ba*h) * sign(p.y*ba.x - p.x*ba.y);
    }

    float3 palette(float n) {
      return 0.5 + 0.5 * sin(float3(0.0, 1.0, 2.0) + n);
    }

    float4 plane(float3 ro, float3 rd, float3 pp, float3 npp, float pd, float3 cp, float3 off, float n) {
      float aa = 3.0 * pd * distance(pp.xy, npp.xy);
      float4 col = float4(0.0);
      float2 p2 = pp.xy;
      p2 -= offsetf(pp.z).xy;
      float2 doff   = ddoffsetf(pp.z).xz;
      float2 ddoff  = doffsetf(pp.z).xz;
      float dd = dot(doff, ddoff);
      p2 = ROT(dd*PI*5.0) * p2;

      float d0 = star5(p2, 0.45, 1.6, 0.2) - 0.02;
      float d1 = d0 - 0.01;
      float d2 = length(p2);
      const float colp = PI*100.0;
      float colaa = aa*200.0;

      col.xyz = palette(0.5*n + 2.0*d2)
              * mix(0.5/(d2*d2), 1.0, smoothstep(-0.5+colaa, 0.5+colaa, sin(d2*colp)))
              / max(3.0*d2*d2, 1e-1);
      col.xyz = mix(col.xyz, float3(2.0), smoothstep(aa, -aa, d1));
      col.w = smoothstep(aa, -aa, -d0);
      return col;
    }

    float3 colorfn(float3 ww, float3 uu, float3 vv, float3 ro, float2 p, float2 iResolution) {
      float2 np = p + 1.0/iResolution.xy;
      float rdd = 1.75; 

      float3 rd  = normalize(p.x*uu + p.y*vv + rdd*ww);
      float3 nrd = normalize(np.x*uu + np.y*vv + rdd*ww);

      float nz = floor(ro.z / planeDist);
      float4 acol = float4(0.0);
      float3 aro = ro;
      float apd = 0.0;

      for (float i = 1.0; i <= furthest; i += 1.0) {
        if (acol.w > 0.95) break;
        float pz = planeDist*nz + planeDist*i;

        float lpd = (pz - aro.z)/rd.z;
        float npd = (pz - aro.z)/nrd.z;
        float cpd = (pz - aro.z)/ww.z;

        float3 pp  = aro + rd*lpd;
        float3 npp = aro + nrd*npd;
        float3 cp  = aro + ww*cpd;
        apd += lpd;

        float3 off = offsetf(pp.z);
        float dz = pp.z - ro.z;
        float fadeIn   = smoothstep(planeDist*furthest, planeDist*fadeFrom, dz);
        float fadeOut  = smoothstep(0.0, planeDist*0.1, dz);
        float fadeOutRI= smoothstep(0.0, planeDist*1.0, dz);
        float ri = mix(1.0, 0.9, fadeOutRI*fadeIn);

        float4 pcol = plane(ro, rd, pp, npp, apd, cp, off, nz + i);
        pcol.w *= fadeOut*fadeIn;
        acol = alphaBlend(pcol, acol);
        aro = pp;
      }

      return acol.xyz * acol.w;
    }

    void amzRender(){
      float2 fragCoord = amzScreenNorm() * screen.zw;
      float2 iResolution = screen.zw;
      float iTime = time * amzp_speed;

      float2 r = iResolution.xy;
      float2 q = fragCoord / r;
      float2 pp = -1.0 + 2.0*q;
      float2 p = pp;
      p.x *= r.x / max(r.y, 1.0);

      float tm = planeDist * iTime;
      float3 ro   = offsetf(tm);
      float3 dro  = doffsetf(tm);
      float3 ddro = ddoffsetf(tm);

      float3 ww = normalize(dro);
      float3 uu = normalize(cross(float3(0.0,1.0,0.0)+ddro, ww));
      float3 vv = cross(ww, uu);

      float3 col = colorfn(ww, uu, vv, ro, p, iResolution);
      col = aces_approx(col * amzp_exposure) * amzp_intensity;
      col = sqrt(max(col, 0.0));


      float4 base = amzTexture(0, amzScreenNorm());
      float4 outC = float4(col, 1.0) * amzp_opacity;
      outC = base * (1.0 - outC.a) + outC;
      amzOutput = outC;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

